function AuthPage({ register = false }) {
  const navigate = useNavigate()
  const [form, setForm] = useState({ username: '', email: '', password: '', full_name: '' })
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const submit = async (event) => {
    event.preventDefault(); setLoading(true); setError('')
    try {
      const data = await api(register ? '/auth/register' : '/auth/login', { method: 'POST', body: JSON.stringify(register ? form : { username: form.username, password: form.password }) })
      localStorage.setItem(TOKEN_KEY, data.access_token); localStorage.setItem('zenheaven_user', JSON.stringify(data.user)); navigate('/dashboard')
    } catch (err) { setError(err.message) } finally { setLoading(false) }
  }
  return <div className="grid min-h-screen bg-cloud lg:grid-cols-[.85fr_1.15fr]"><div className="hidden overflow-hidden bg-ink p-10 text-white lg:flex lg:flex-col lg:justify-between"><Logo dark /><div><div className="mb-8 grid h-14 w-14 place-items-center rounded-2xl bg-mint text-ink"><Sparkles size={25} /></div><h1 className="max-w-md font-display text-5xl font-semibold leading-[1.05] tracking-[-.05em]">A softer place to start.</h1><p className="mt-6 max-w-sm leading-7 text-slate-400">Your account is a private space for small rituals, honest reflection, and meaningful support.</p></div><p className="text-sm text-slate-500">Made for the full spectrum of being human.</p></div><div className="flex items-center justify-center p-6 sm:p-10"><div className="w-full max-w-md"><div className="mb-10 lg:hidden"><Logo /></div><Link to="/" className="mb-10 inline-flex items-center gap-1 text-sm font-medium text-slate-500 hover:text-ink"><ChevronRight className="rotate-180" size={15} /> Back to home</Link><Pill color="purple">{register ? 'Create your space' : 'Welcome back'}</Pill><h2 className="mt-5 font-display text-4xl font-semibold tracking-[-.045em]">{register ? 'Start where you are.' : 'Good to see you.'}</h2><p className="mt-3 text-slate-500">{register ? 'A few details, then your wellbeing workspace is ready.' : 'Pick up exactly where you left off.'}</p><form onSubmit={submit} className="mt-8 space-y-4">{register && <Field label="Your name" placeholder="Alex Morgan" value={form.full_name} onChange={(value) => setForm({ ...form, full_name: value })} />}{register && <Field label="Email address" type="email" placeholder="you@example.com" value={form.email} onChange={(value) => setForm({ ...form, email: value })} />}{<Field label="Username" placeholder="alexmorgan" value={form.username} onChange={(value) => setForm({ ...form, username: value })} />}{<Field label="Password" type="password" placeholder="At least 6 characters" value={form.password} onChange={(value) => setForm({ ...form, password: value })} />}{error && <p className="rounded-lg bg-red-50 p-3 text-sm text-red-600">{error}</p>}<Button variant="brand" className="mt-2 w-full" disabled={loading}>{loading ? <LoaderCircle size={17} className="animate-spin" /> : register ? 'Create my account' : 'Sign in'} {!loading && <ArrowRight size={16} />}</Button></form><p className="mt-8 text-center text-sm text-slate-500">{register ? 'Already have an account?' : "Don't have an account?"} <Link className="font-bold text-brand hover:text-ink" to={register ? '/login' : '/register'}>{register ? 'Sign in' : 'Get started'}</Link></p><p className="mt-12 text-center text-xs leading-5 text-slate-400">By continuing, you agree to ZenHeaven's terms and acknowledge our privacy policy.</p></div></div></div>
}

