function Dashboard() {
  const [data, setData] = useState({ balance: 240, streak: 7, journal: 12, threads: 3 })
  const [user, setUser] = useState(() => JSON.parse(localStorage.getItem('zenheaven_user') || 'null'))
  useEffect(() => {
    Promise.allSettled([api('/coins/balance'), api('/coins/streak'), api('/journal/entries'), api('/mental-health/threads')]).then(([balance, streak, journal, threads]) => setData({ balance: balance.value?.balance ?? 240, streak: streak.value?.current_streak ?? 7, journal: journal.value?.length ?? 12, threads: threads.value?.total_count ?? 3 }))
    api('/auth/me').then((nextUser) => { setUser(nextUser); localStorage.setItem('zenheaven_user', JSON.stringify(nextUser)) }).catch(() => {})
  }, [])
  const firstName = (user?.full_name || user?.username || 'Alex').split(' ')[0]
  return <><div className="mb-8 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-sm font-medium text-slate-500">Monday, 14 October 2024</p><h1 className="mt-1 font-display text-3xl font-semibold tracking-[-.045em] sm:text-4xl">Good morning, {firstName} <span className="inline-block">✦</span></h1><p className="mt-2 text-sm text-slate-500">A little check-in before your day gets going.</p></div><Link to="/journal"><Button variant="light"><Plus size={16} /> New journal entry</Button></Link></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric icon={<Heart />} label="Current mood" value="Calm" note="Feeling grounded" tint="purple" /><Metric icon={<Target />} label="Daily streak" value={`${data.streak} days`} note="Keep your rhythm" tint="green" /><Metric icon={<Coins />} label="Calm coins" value={data.balance} note="+15 this week" tint="orange" /><Metric icon={<TrendingUp />} label="Journal entries" value={data.journal} note="3 this month" tint="blue" /></div><div className="mt-6 grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><Card className="overflow-hidden p-0"><div className="flex items-start justify-between p-5 pb-0"><div><Pill color="green">Your rhythm</Pill><h2 className="mt-3 text-lg font-bold">Mood, over time</h2><p className="mt-1 text-sm text-slate-400">A gentle view of how you've been feeling.</p></div><button className="rounded-lg p-2 text-slate-400 hover:bg-slate-100"><MoreHorizontal size={18} /></button></div><div className="px-5 pb-5 pt-7"><div className="chart-grid relative flex h-52 items-end gap-2 sm:gap-5"><div className="mood-line absolute inset-x-0 bottom-7 h-32"><svg viewBox="0 0 600 130" preserveAspectRatio="none" className="h-full w-full overflow-visible"><defs><linearGradient id="moodFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#635bff" stopOpacity=".2" /><stop offset="100%" stopColor="#635bff" stopOpacity="0" /></linearGradient></defs><path d="M0,92 C35,86 44,101 76,82 S122,72 150,84 S198,52 228,67 S266,85 305,54 S344,67 378,38 S420,59 452,45 S500,24 528,42 S562,31 600,17 V130 H0Z" fill="url(#moodFill)" /><path d="M0,92 C35,86 44,101 76,82 S122,72 150,84 S198,52 228,67 S266,85 305,54 S344,67 378,38 S420,59 452,45 S500,24 528,42 S562,31 600,17" fill="none" stroke="#635bff" strokeWidth="3" vectorEffect="non-scaling-stroke" /></svg></div>{['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map((day, index) => <div key={day} className="relative z-[1] flex flex-1 flex-col items-center justify-end gap-3"><div className={cn('h-2 w-2 rounded-full', index === 6 ? 'bg-brand ring-4 ring-brand/10' : 'bg-slate-200')} /><span className="text-[10px] font-semibold text-slate-400">{day}</span></div>)}</div><div className="mt-5 flex items-center gap-5 text-xs font-semibold text-slate-400"><span className="flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-brand" />Balanced</span><span className="flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-slate-200" />Check-in days</span></div></div></Card><Card><SectionTitle title="Today at a glance" action={<button className="text-slate-400"><MoreHorizontal size={18} /></button>} /><div className="space-y-2"><QuickAction icon={<MessageCircle />} title="Talk to your companion" note="A 5-minute reset" tint="purple" to="/chat" /><QuickAction icon={<PenLine />} title="Capture a thought" note="Journal your morning" tint="green" to="/journal" /><QuickAction icon={<Music2 />} title="Find your focus" note="Curated for calm" tint="orange" to="/music" /></div><Link to="/dashboard" className="mt-5 flex items-center justify-center gap-2 border-t border-slate-100 pt-4 text-xs font-bold text-brand">View your plan <ArrowRight size={14} /></Link></Card></div><div className="mt-5 grid gap-5 lg:grid-cols-3"><Card className="lg:col-span-2"><SectionTitle title="A note from your future self" action={<Sparkles size={16} className="text-brand" />} /><div className="flex gap-4 rounded-xl bg-[#f7f6ff] p-4"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-full bg-white text-brand shadow-sm"><Lightbulb size={18} /></div><div><p className="text-sm font-semibold leading-6 text-ink">“You are allowed to take the next step slowly. Progress doesn't need to be loud to be real.”</p><p className="mt-3 text-xs font-semibold text-brand">A reflection for today</p></div></div></Card><Card><SectionTitle title="Private by design" /><div className="flex items-start gap-3"><ShieldCheck className="mt-0.5 text-emerald-600" size={19} /><p className="text-xs leading-5 text-slate-500">Your journal, conversations, and care choices are protected with thoughtful privacy defaults.</p></div><button className="mt-4 text-xs font-bold text-ink underline underline-offset-4">Learn about privacy</button></Card></div></>
}

function Metric({ icon, label, value, note, tint }) { const tintStyles = { purple: 'bg-[#efedff] text-brand', green: 'bg-[#e9faf3] text-emerald-600', orange: 'bg-[#fff0e7] text-orange-500', blue: 'bg-[#eaf4ff] text-blue-600' }; return <Card className="p-4"><div className="flex items-start justify-between"><span className={cn('grid h-9 w-9 place-items-center rounded-lg', tintStyles[tint])}>{icon}</span><ArrowUpRight size={15} className="text-slate-300" /></div><p className="mt-5 text-xs font-semibold text-slate-400">{label}</p><p className="mt-1 text-2xl font-bold tracking-[-.03em]">{value}</p><p className="mt-1 text-xs text-slate-400">{note}</p></Card> }
function QuickAction({ icon, title, note, tint, to }) { const styles = { purple: 'bg-[#efedff] text-brand', green: 'bg-[#e9faf3] text-emerald-600', orange: 'bg-[#fff0e7] text-orange-500' }; return <Link to={to} className="flex items-center gap-3 rounded-xl p-2 transition hover:bg-slate-50"><span className={cn('grid h-9 w-9 place-items-center rounded-lg', styles[tint])}>{icon}</span><span className="flex-1"><strong className="block text-xs font-bold">{title}</strong><small className="mt-0.5 block text-[11px] text-slate-400">{note}</small></span><ChevronRight size={15} className="text-slate-300" /></Link> }

function Chat() {
  const [threads, setThreads] = useState([])
  const [active, setActive] = useState(null)
  const [messages, setMessages] = useState([{ role: 'assistant', content: 'Hi, I’m here with you. What feels most present for you today?' }])
  const [input, setInput] = useState('')
  const [thinking, setThinking] = useState(false)
  const [status, setStatus] = useState('Ready when you are')
  useEffect(() => { api('/mental-health/threads').then((data) => setThreads(data.threads || [])).catch(() => {}) }, [])
  const loadThread = (thread) => { setActive(thread.id); api(`/mental-health/threads/${thread.id}`).then((data) => setMessages((data.messages || []).map((message) => ({ role: message.is_user ? 'user' : 'assistant', content: message.content })))).catch(() => {}) }
  const send = async (event) => {
    event?.preventDefault(); const message = input.trim(); if (!message || thinking) return
    setInput(''); setMessages((current) => [...current, { role: 'user', content: message }]); setThinking(true); setStatus('Thinking with you…')
    try {
      const response = await fetch(`${API_URL}/mental-health/chat/stream`, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${localStorage.getItem(TOKEN_KEY)}` }, body: JSON.stringify({ message, thread_id: active }) })
      if (!response.ok || !response.body) throw new Error('stream unavailable')
      const reader = response.body.getReader(); const decoder = new TextDecoder(); let buffer = ''; let answer = ''; setMessages((current) => [...current, { role: 'assistant', content: '' }])
      while (true) {
        const { value, done } = await reader.read(); if (done) break; buffer += decoder.decode(value, { stream: true }); const chunks = buffer.split('\n\n'); buffer = chunks.pop() || ''
        chunks.forEach((chunk) => { if (!chunk.startsWith('data:')) return; try { const payload = JSON.parse(chunk.replace(/^data:\s*/, '')); if (payload.type === 'thread_id') setActive(payload.data); if (payload.type === 'thinking') setStatus(payload.data); if (payload.type === 'token') { answer += payload.data; setMessages((current) => { const next = [...current]; next[next.length - 1] = { role: 'assistant', content: answer }; return next }) } if (payload.type === 'complete') setStatus(`You earned ${payload.data.coins_earned || 5} calm coins`) } catch (_) {} })
      }
    } catch (_) { setMessages((current) => [...current, { role: 'assistant', content: 'I’m here with you. Take one slow breath, and try putting the feeling into a few simple words. We can start there.' }]); setStatus('A gentle response, even offline') } finally { setThinking(false) }
  }
  const newChat = () => { setActive(null); setMessages([{ role: 'assistant', content: 'Hi, I’m here with you. What feels most present for you today?' }]); setStatus('Ready when you are') }
  return <><PageHeader eyebrow="AI companion" title="A place to say it out loud." copy="A supportive space for the thoughts that are hard to organize. Your companion listens, reflects, and helps you find a next step." action={<Button variant="light" onClick={newChat}><Plus size={16} /> New conversation</Button>} /><div className="grid gap-5 xl:grid-cols-[260px_1fr_250px]"><Card className="hidden h-[650px] p-3 xl:block"><div className="flex items-center justify-between px-2 py-2"><span className="text-xs font-bold uppercase tracking-[.1em] text-slate-400">Conversations</span><button onClick={newChat} className="rounded-lg p-1.5 text-brand hover:bg-[#efedff]"><Plus size={16} /></button></div><div className="mt-3 space-y-1">{threads.length ? threads.map((thread) => <button key={thread.id} onClick={() => loadThread(thread)} className={cn('w-full rounded-xl p-3 text-left transition', active === thread.id ? 'bg-[#f1efff]' : 'hover:bg-slate-50')}><p className="truncate text-xs font-bold">{thread.title}</p><p className="mt-1 truncate text-[11px] text-slate-400">{thread.last_message || 'No messages yet'}</p></button>) : <div className="px-2 pt-8 text-center text-xs leading-5 text-slate-400">Your conversations will appear here.</div>}</div></Card><Card className="flex h-[650px] flex-col overflow-hidden p-0"><div className="flex items-center gap-3 border-b border-slate-100 px-5 py-4"><span className="grid h-9 w-9 place-items-center rounded-xl bg-ink text-mint"><Sparkles size={17} /></span><div><p className="text-sm font-bold">ZenHeaven companion</p><p className="text-[11px] text-emerald-600"><span className="mr-1 inline-block h-1.5 w-1.5 rounded-full bg-emerald-500" /> {status}</p></div><button className="ml-auto text-slate-400"><MoreHorizontal size={18} /></button></div><div className="flex-1 space-y-5 overflow-y-auto bg-[#fbfcfe] p-5">{messages.map((message, index) => <div key={`${message.role}-${index}`} className={cn('flex gap-3', message.role === 'user' && 'flex-row-reverse')}><span className={cn('grid h-8 w-8 shrink-0 place-items-center rounded-full text-xs font-bold', message.role === 'assistant' ? 'bg-ink text-mint' : 'bg-[#c9c1ff] text-[#4138aa]')}>{message.role === 'assistant' ? <Leaf size={15} /> : 'A'}</span><div className={cn('max-w-[78%] rounded-2xl px-4 py-3 text-sm leading-6', message.role === 'assistant' ? 'rounded-tl-sm bg-white text-slate-600 shadow-sm' : 'rounded-tr-sm bg-brand text-white')}>{message.content || <LoaderCircle size={16} className="animate-spin" />}</div></div>)}</div><form onSubmit={send} className="border-t border-slate-100 bg-white p-4"><div className="flex items-center gap-2 rounded-xl border border-slate-200 bg-cloud p-1.5 focus-within:border-brand focus-within:ring-4 focus-within:ring-brand/10"><input value={input} onChange={(event) => setInput(event.target.value)} placeholder="Share what's on your mind…" className="h-10 flex-1 bg-transparent px-3 text-sm outline-none placeholder:text-slate-400" /><button aria-label="Send message" className="grid h-10 w-10 place-items-center rounded-lg bg-ink text-white transition hover:bg-brand disabled:opacity-40" disabled={!input.trim() || thinking}><ArrowUpRight size={17} /></button></div><p className="mt-3 text-center text-[10px] text-slate-400">ZenHeaven is a support tool, not a replacement for professional or emergency care.</p></form></Card><div className="space-y-4"><Card><SectionTitle title="Try starting with" /><div className="space-y-2">{['I feel a little overwhelmed', 'Help me find some calm', 'I want to understand my mood'].map((prompt) => <button key={prompt} onClick={() => setInput(prompt)} className="flex w-full items-center justify-between rounded-lg bg-cloud p-3 text-left text-xs font-semibold text-slate-600 hover:bg-[#efedff] hover:text-brand"><span>{prompt}</span><ArrowUpRight size={14} /></button>)}</div></Card><Card className="border-emerald-100 bg-emerald-50/50"><ShieldCheck size={19} className="text-emerald-600" /><p className="mt-3 text-sm font-bold">A private conversation</p><p className="mt-1 text-xs leading-5 text-slate-500">Your messages are connected to your account so you can return to them, never to judge you.</p></Card></div></div></>
}

function Journal() {
  const [entries, setEntries] = useState([])
  const [prompts, setPrompts] = useState([])
  const [insights, setInsights] = useState(null)
  const [content, setContent] = useState('')
  const [mood, setMood] = useState('calm')
  const [loading, setLoading] = useState(false)
  const [notice, setNotice] = useState('')
  const refresh = () => { api('/journal/entries').then(setEntries).catch(() => setEntries([])); api('/journal/prompts').then(setPrompts).catch(() => setPrompts([])); api('/journal/insights').then(setInsights).catch(() => {}) }
  useEffect(refresh, [])
  const save = async (event) => { event.preventDefault(); if (!content.trim()) return; setLoading(true); try { const entry = await api('/journal/entries', { method: 'POST', body: JSON.stringify({ content, mood, tags: ['reflection'] }) }); setEntries((current) => [entry, ...current]); setContent(''); setNotice('+10 calm coins earned for showing up'); setTimeout(() => setNotice(''), 3500) } catch (err) { setNotice(err.message) } finally { setLoading(false) } }
  const remove = async (id) => { try { await api(`/journal/entries/${id}`, { method: 'DELETE' }); setEntries((current) => current.filter((entry) => (entry._id || entry.id) !== id)) } catch (_) {} }
  const visibleEntries = entries.length ? entries : [{ _id: 'demo-1', title: 'A steadier morning', content: 'I noticed I was rushing today, so I took a few minutes to sit with my coffee and breathe. It helped me feel more present.', mood: 'calm', created_at: new Date().toISOString() }, { _id: 'demo-2', title: 'Making room for change', content: 'Some things feel uncertain, but I am learning that I can take one decision at a time.', mood: 'hopeful', created_at: new Date(Date.now() - 86400000 * 2).toISOString() }]
  return <><PageHeader eyebrow="Your journal" title="Make a little room." copy="A private place to notice what’s happening within you. No perfect words required." action={<Pill color="green"><span className="mr-1">✦</span> {entries.length || 12} entries captured</Pill>} /><div className="grid gap-5 xl:grid-cols-[1fr_310px]"><div><Card><div className="flex items-center justify-between"><div><h2 className="text-lg font-bold">How are you arriving today?</h2><p className="mt-1 text-sm text-slate-400">Write freely — your words don't need to be polished.</p></div><PenLine size={20} className="text-brand" /></div><form onSubmit={save} className="mt-5"><textarea value={content} onChange={(event) => setContent(event.target.value)} placeholder="Today, I noticed…" className="min-h-[175px] w-full resize-none rounded-xl border border-slate-200 bg-cloud p-4 text-sm leading-6 outline-none placeholder:text-slate-400 focus:border-brand focus:ring-4 focus:ring-brand/10" /><div className="mt-4 flex flex-col gap-3 sm:flex-row sm:items-center"><div className="flex items-center gap-2"><span className="text-xs font-bold text-slate-400">Mood</span>{['calm', 'hopeful', 'tired', 'anxious'].map((option) => <button type="button" key={option} onClick={() => setMood(option)} className={cn('rounded-lg px-2.5 py-1.5 text-xs font-semibold capitalize transition', mood === option ? 'bg-[#efedff] text-brand' : 'bg-slate-100 text-slate-500 hover:bg-slate-200')}>{option}</button>)}</div><Button variant="brand" className="sm:ml-auto" disabled={loading}>{loading ? <LoaderCircle size={16} className="animate-spin" /> : <PenLine size={16} />} Save reflection</Button></div>{notice && <p className="mt-3 text-xs font-bold text-emerald-600">{notice}</p>}</form></Card><div className="mt-7"><SectionTitle title="Recent reflections" action={<button className="text-xs font-bold text-brand">View all</button>} /><div className="space-y-3">{visibleEntries.map((entry) => { const id = entry._id || entry.id; return <Card key={id} className="group p-4"><div className="flex items-start gap-4"><div className={cn('grid h-10 w-10 shrink-0 place-items-center rounded-xl', entry.mood === 'hopeful' ? 'bg-emerald-50 text-emerald-600' : 'bg-[#efedff] text-brand')}><PenLine size={17} /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="truncate text-sm font-bold">{entry.title || 'A moment of reflection'}</h3><Pill color={entry.mood === 'hopeful' ? 'green' : 'purple'}>{entry.mood || 'reflected'}</Pill></div><p className="mt-2 line-clamp-2 text-sm leading-6 text-slate-500">{entry.content}</p><p className="mt-3 text-[11px] font-medium text-slate-400">{new Date(entry.created_at || Date.now()).toLocaleDateString(undefined, { month: 'long', day: 'numeric', year: 'numeric' })}</p></div><button onClick={() => !id.startsWith('demo') && remove(id)} className="invisible rounded-lg p-2 text-slate-300 hover:bg-red-50 hover:text-red-500 group-hover:visible"><Trash2 size={15} /></button></div></Card> })}</div></div></div><div className="space-y-5"><Card className="bg-ink text-white"><div className="flex items-center gap-2 text-mint"><Sparkles size={16} /><span className="text-xs font-bold uppercase tracking-[.1em]">Writing prompt</span></div><p className="mt-5 font-display text-xl font-semibold leading-7">{prompts[0]?.prompt || 'What would feel like a kind choice for yourself today?'}</p><button onClick={() => setContent(prompts[0]?.prompt || '')} className="mt-6 flex items-center gap-2 text-xs font-bold text-mint">Use this prompt <ArrowRight size={14} /></button></Card><Card><SectionTitle title="Your patterns" action={<BarChart3 size={16} className="text-brand" />} /><div className="space-y-4"><div className="flex items-center justify-between"><span className="text-xs text-slate-500">Reflections</span><strong className="text-sm">{insights?.total_entries ?? entries.length ?? 12}</strong></div><div className="h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full w-[72%] rounded-full bg-brand" /></div><p className="text-xs leading-5 text-slate-400">{insights?.message || 'You are building a thoughtful practice. Keep going at your own pace.'}</p></div></Card><Card><SectionTitle title="Small reminder" /><div className="flex gap-3"><Heart size={17} className="mt-0.5 text-coral" /><p className="text-xs leading-5 text-slate-500">You can be honest here. The point is not to document a perfect day — just to meet the real one.</p></div></Card></div></div></>
}

function Books() {
  const [books, setBooks] = useState(fallbackBooks)
  const [query, setQuery] = useState('')
  const [mood, setMood] = useState('balanced')
  const [searching, setSearching] = useState(false)
  const search = async (event) => { event?.preventDefault(); if (!query.trim()) return; setSearching(true); try { const data = await api(`/books/search?q=${encodeURIComponent(query)}&max_results=10`); setBooks(data.books?.length ? data.books : fallbackBooks) } catch (_) {} finally { setSearching(false) } }
  useEffect(() => { api('/books/recommend-by-mood').then((data) => { if (data.books?.length) { setMood(data.mood); setBooks(data.books) } }).catch(() => {}) }, [])
  return <><PageHeader eyebrow="Reading room" title="A good book can shift a day." copy="Curated recommendations for the emotional weather you're in — plus a place to search for the one you've been looking for." action={<form onSubmit={search} className="flex h-11 w-full max-w-xs items-center rounded-xl border border-slate-200 bg-white px-3 shadow-sm"><Search size={16} className="text-slate-400" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search the room…" className="min-w-0 flex-1 bg-transparent px-2 text-sm outline-none" /><button aria-label="Search" className="text-brand">{searching ? <LoaderCircle size={15} className="animate-spin" /> : <ArrowRight size={16} />}</button></form>} /><div className="mb-6 flex flex-wrap items-center gap-2"><span className="mr-1 text-xs font-bold text-slate-400">Browse by feeling</span>{['balanced', 'calm', 'anxious', 'hopeful', 'tired'].map((item) => <button key={item} onClick={() => setMood(item)} className={cn('rounded-full px-3 py-1.5 text-xs font-bold capitalize transition', mood === item ? 'bg-ink text-white' : 'bg-white text-slate-500 hover:bg-slate-100')}>{item}</button>)}</div><div className="mb-5 flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.12em] text-slate-400">For a {mood} mind</p><h2 className="mt-1 text-xl font-bold">Books to meet you there</h2></div><span className="text-xs text-slate-400">{books.length} titles</span></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">{books.map((book) => <BookCard key={book.id} book={book} />)}</div><div className="mt-6 rounded-2xl bg-[#f1efff] p-6 sm:flex sm:items-center sm:justify-between"><div><Pill color="purple">A mindful detour</Pill><h3 className="mt-3 text-lg font-bold">Not sure what you need?</h3><p className="mt-1 text-sm text-slate-500">Tell us how you're feeling in your journal and we'll find the next chapter for you.</p></div><Link to="/journal" className="mt-4 inline-flex items-center gap-2 text-sm font-bold text-brand sm:mt-0">Write a check-in <ArrowRight size={15} /></Link></div></>
}
function BookCard({ book }) { const [similar, setSimilar] = useState(false); return <Card className="group flex h-full flex-col overflow-hidden p-0 transition hover:-translate-y-1"><div className="relative h-52 overflow-hidden bg-slate-100">{book.image_url ? <img src={book.image_url} alt="" className="h-full w-full object-cover transition duration-500 group-hover:scale-105" /> : <div className="grid h-full place-items-center text-slate-300"><BookOpen size={42} /></div>}<button onClick={() => setSimilar(!similar)} className="absolute right-3 top-3 grid h-8 w-8 place-items-center rounded-full bg-white/90 text-slate-500 shadow-sm hover:text-brand"><Heart size={15} fill={similar ? 'currentColor' : 'none'} /></button></div><div className="flex flex-1 flex-col p-4"><p className="text-xs font-bold text-brand">{book.author || 'ZenHeaven pick'}</p><h3 className="mt-2 line-clamp-2 text-base font-bold leading-5">{book.title}</h3><p className="mt-2 line-clamp-3 flex-1 text-xs leading-5 text-slate-500">{book.description || 'A thoughtful read for your wellbeing shelf.'}</p><button onClick={async () => { try { await api(`/books/recommend/${book.id}`) } catch (_) {} }} className="mt-5 flex items-center gap-1 text-xs font-bold text-ink">Find similar <ArrowUpRight size={14} /></button></div></Card> }

function Music() {
  const [songs, setSongs] = useState(fallbackSongs)
  const [selected, setSelected] = useState('')
  const [recommendations, setRecommendations] = useState([])
  const [loading, setLoading] = useState(false)
  useEffect(() => { api('/songs').then((data) => setSongs(data.songs?.slice(0, 20) || fallbackSongs)).catch(() => {}) }, [])
  const recommend = async () => { if (!selected) return; setLoading(true); try { const data = await api(`/recommend?song=${encodeURIComponent(selected)}`); setRecommendations(data.recommendations || []) } catch (_) { setRecommendations([]) } finally { setLoading(false) } }
  return <><PageHeader eyebrow="Your soundtrack" title="Let the room change." copy="Music can give a feeling somewhere to land. Start with a song and build a little atmosphere around it." action={<Pill color="orange"><Music2 size={13} className="mr-1.5" /> Mood: focused</Pill>} /><div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><Card className="overflow-hidden bg-ink text-white"><div className="relative"><div className="absolute -right-16 -top-16 h-48 w-48 rounded-full bg-brand/40 blur-3xl" /><Pill color="green">Soundtrack builder</Pill><h2 className="relative mt-5 max-w-sm font-display text-3xl font-semibold leading-tight tracking-[-.04em]">Choose a starting point. We'll follow the feeling.</h2><p className="relative mt-4 text-sm leading-6 text-slate-400">Pick a song you already love and discover a few that share its shape.</p><div className="relative mt-8"><label className="text-xs font-bold text-slate-300">Starting song</label><div className="mt-2 flex rounded-xl border border-white/15 bg-white/10 p-1"><select value={selected} onChange={(event) => setSelected(event.target.value)} className="h-11 min-w-0 flex-1 bg-transparent px-3 text-sm text-white outline-none"><option value="" className="text-ink">Choose a song</option>{songs.map((song) => <option key={song} value={song} className="text-ink">{song}</option>)}</select><Button variant="brand" className="h-11" onClick={recommend} disabled={loading || !selected}>{loading ? <LoaderCircle size={16} className="animate-spin" /> : <Sparkles size={16} />} Tune in</Button></div></div></div><div className="relative mt-10 flex items-end gap-1 opacity-70">{Array.from({ length: 28 }, (_, index) => <span key={index} className="music-wave" style={{ height: `${18 + ((index * 17) % 48)}px` }} />)}</div></Card><Card><SectionTitle title={recommendations.length ? 'Made from your starting point' : 'A quiet playlist for right now'} action={<button className="text-xs font-bold text-brand">Open player</button>} /><div className="space-y-1">{(recommendations.length ? recommendations : songs.slice(0, 5)).map((song, index) => { const name = typeof song === 'string' ? song : song.name; const artist = typeof song === 'string' ? '' : song.artist; return <div key={`${name}-${index}`} className="group flex items-center gap-3 rounded-xl p-3 hover:bg-cloud"><span className="grid h-10 w-10 place-items-center rounded-lg bg-[#f1efff] text-brand">{song.album_cover_url ? <img src={song.album_cover_url} alt="" className="h-full w-full rounded-lg object-cover" /> : <Music2 size={17} />}</span><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{name}</p><p className="mt-0.5 text-xs text-slate-400">{artist || 'Curated for your current pace'}</p></div><button className="grid h-8 w-8 place-items-center rounded-full border border-slate-200 text-slate-400 transition hover:border-brand hover:bg-brand hover:text-white"><Play size={13} fill="currentColor" /></button></div> })}</div><div className="mt-5 rounded-xl bg-cloud p-4"><div className="flex items-center gap-2"><Zap size={15} className="text-orange-500" /><span className="text-xs font-bold">Try a listening ritual</span></div><p className="mt-2 text-xs leading-5 text-slate-500">Put your phone face down, press play, and notice three things you can hear before the track ends.</p></div></Card></div></>
}

function Therapists() {
  const [therapists, setTherapists] = useState(fallbackTherapists)
  const [specialization, setSpecialization] = useState('')
  const [selected, setSelected] = useState(null)
  const [notice, setNotice] = useState('')
  useEffect(() => { api('/therapists/').then((data) => { if (data?.length) setTherapists(data) }).catch(() => {}) }, [])
  const filtered = therapists.filter((therapist) => !specialization || therapist.specializations?.some((item) => item.toLowerCase().includes(specialization.toLowerCase())))
  const book = async (therapist) => { try { const detail = await api(`/therapists/${therapist._id}`); const slot = detail.available_slots?.[0]; if (!slot) { setNotice('This clinician’s availability will appear once the care network is connected.'); return } const user = JSON.parse(localStorage.getItem('zenheaven_user') || '{}'); await api('/therapists/appointments', { method: 'POST', body: JSON.stringify({ user_id: user.id, therapist_id: therapist._id, date: slot.start_time, start_time: slot.start_time, end_time: slot.end_time, session_type: 'video' }) }); setNotice(`Your session with ${therapist.name} is booked.`) } catch (_) { setNotice('Choose a time from the clinician profile to book your session.') } }
  return <><PageHeader eyebrow="Care network" title="Human support, when you're ready." copy="Browse licensed professionals by approach and specialty. You can take your time choosing a fit." action={<Button variant="light"><CalendarDays size={16} /> My appointments</Button>} /><div className="mb-6 flex flex-wrap gap-2"><button onClick={() => setSpecialization('')} className={cn('rounded-full px-3 py-1.5 text-xs font-bold', !specialization ? 'bg-ink text-white' : 'bg-white text-slate-500')}>All approaches</button>{['Anxiety', 'Depression', 'Relationships', 'Grief', 'Stress'].map((item) => <button key={item} onClick={() => setSpecialization(item)} className={cn('rounded-full px-3 py-1.5 text-xs font-bold', specialization === item ? 'bg-ink text-white' : 'bg-white text-slate-500')}>{item}</button>)}</div>{notice && <div className="mb-5 flex items-center gap-2 rounded-xl bg-emerald-50 p-4 text-sm font-semibold text-emerald-700"><Check size={17} />{notice}</div>}<div className="grid gap-4 lg:grid-cols-2">{filtered.map((therapist) => <Card key={therapist._id} className="transition hover:-translate-y-0.5"><div className="flex gap-4"><img src={therapist.photo_url || `https://i.pravatar.cc/160?u=${therapist._id}`} alt="" className="h-20 w-20 rounded-2xl object-cover" /><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><div><h3 className="text-base font-bold">{therapist.name}</h3><p className="mt-1 text-xs text-slate-400">{therapist.experience_years} years experience · {therapist.languages?.join(', ')}</p></div><span className="flex items-center gap-1 text-xs font-bold text-orange-500"><Star size={13} fill="currentColor" /> {therapist.rating}</span></div><div className="mt-3 flex flex-wrap gap-1.5">{therapist.specializations?.slice(0, 3).map((item) => <Pill key={item} color="purple">{item}</Pill>)}</div></div></div><p className="mt-4 line-clamp-2 text-sm leading-6 text-slate-500">{therapist.bio}</p><div className="mt-5 flex items-center justify-between border-t border-slate-100 pt-4"><p className="text-xs text-slate-400">from <strong className="text-sm text-ink">${therapist.hourly_rate}</strong> / session</p><Button variant="light" className="h-9 text-xs" onClick={() => { setSelected(therapist); book(therapist) }}>View availability <ArrowRight size={14} /></Button></div></Card>)}</div>{selected && <div className="fixed inset-0 z-40 grid place-items-center bg-ink/30 p-5" onClick={() => setSelected(null)}><div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-soft" onClick={(event) => event.stopPropagation()}><div className="flex items-start justify-between"><div><Pill color="green">Your care, your choice</Pill><h2 className="mt-3 text-xl font-bold">{selected.name}</h2></div><button onClick={() => setSelected(null)} className="text-slate-400"><X size={18} /></button></div><p className="mt-4 text-sm leading-6 text-slate-500">{selected.bio}</p><div className="mt-6 rounded-xl bg-cloud p-4"><p className="text-xs font-bold text-slate-400">Session format</p><div className="mt-3 flex gap-2"><button className="flex-1 rounded-lg bg-ink py-2 text-xs font-bold text-white">Video</button><button className="flex-1 rounded-lg bg-white py-2 text-xs font-bold text-slate-500">Phone</button></div></div><Button variant="brand" className="mt-5 w-full" onClick={() => book(selected)}>Book first available session <ArrowRight size={15} /></Button></div></div>}</>
}

function CoinsPage() {
  const [balance, setBalance] = useState(240)
  const [transactions, setTransactions] = useState([])
  const [goals, setGoals] = useState([])
  const [achievements, setAchievements] = useState([])
  const [streak, setStreak] = useState({ current_streak: 7, longest_streak: 12 })
  const [spending, setSpending] = useState(false)
  useEffect(() => {
    api('/coins/balance').then((data) => setBalance(data.balance)).catch(() => {})
    api('/coins/transactions').then(setTransactions).catch(() => {})
    api('/coins/daily-goals').then(setGoals).catch(() => {})
    api('/coins/achievements').then(setAchievements).catch(() => {})
    api('/coins/streak').then(setStreak).catch(() => {})
  }, [])
  const displayGoals = goals.length ? goals : [{ id: 1, title: 'Chat with AI Therapist', target: 1, current: 1, coins: 10, completed: true, icon: 'MessageCircle' }, { id: 2, title: 'Write in Journal', target: 1, current: 0, coins: 15, completed: false, icon: 'BookOpen' }, { id: 3, title: 'Complete Mood Check', target: 1, current: 0, coins: 5, completed: false, icon: 'Heart' }]
  const displayAchievements = achievements.length ? achievements : [{ id: 1, title: 'First Steps', description: 'Started your mental health journey', coins: 50, unlocked: true }, { id: 2, title: 'Consistent Chatter', description: 'Chat for 7 days in a row', coins: 100, unlocked: false }, { id: 3, title: 'Wellness Warrior', description: 'Earn 1000 total coins', coins: 300, unlocked: false }]
  const spend = async () => { setSpending(true); try { const data = await api('/coins/spend', { method: 'POST', body: JSON.stringify({ amount: 100, source: 'rewards', description: 'Unlocked premium insights' }) }); setBalance(data.new_balance) } catch (_) {} finally { setSpending(false) } }
  return <><PageHeader eyebrow="Calm coins" title="Notice the progress." copy="Every small act of care adds up. Calm coins are a gentle way to see your consistency — never a score to chase." action={<Button variant="light" onClick={spend} disabled={spending}><Sparkles size={16} /> Unlock an insight · 100</Button>} /><div className="grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><div className="relative overflow-hidden rounded-2xl bg-ink p-6 text-white shadow-soft sm:p-8"><div className="coin-glow" /><div className="relative"><Pill color="green">Your balance</Pill><div className="mt-6 flex items-end gap-3"><span className="font-display text-6xl font-semibold tracking-[-.06em]">{balance}</span><span className="mb-2 text-sm font-bold text-slate-400">calm coins</span></div><p className="mt-3 max-w-xs text-sm leading-6 text-slate-400">You earned 45 coins this week by choosing yourself, consistently.</p><div className="mt-8 flex items-center gap-2 text-xs font-bold text-mint"><TrendingUp size={15} /> 23% more than last week</div></div><Coins className="absolute bottom-6 right-7 text-mint/20" size={115} /></div><Card><SectionTitle title="Your current rhythm" /><div className="flex items-center gap-5"><div className="relative grid h-28 w-28 place-items-center rounded-full" style={{ background: 'conic-gradient(#635bff 0 68%, #eeecf8 68% 100%)' }}><div className="grid h-20 w-20 place-items-center rounded-full bg-white"><div className="text-center"><strong className="block text-2xl">{streak.current_streak}</strong><span className="text-[10px] font-bold uppercase tracking-wider text-slate-400">days</span></div></div></div><div><p className="text-sm font-bold">A steady practice</p><p className="mt-1 text-xs leading-5 text-slate-400">Your longest streak is {streak.longest_streak} days. Keep finding what works.</p></div></div></Card></div><div className="mt-5 grid gap-5 xl:grid-cols-[1fr_1fr]"><Card><SectionTitle title="Daily goals" action={<span className="text-xs text-slate-400">{displayGoals.filter((goal) => goal.completed).length}/{displayGoals.length} complete</span>} /><div className="space-y-2">{displayGoals.map((goal) => <div key={goal.id} className={cn('flex items-center gap-3 rounded-xl p-3', goal.completed ? 'bg-emerald-50/70' : 'bg-cloud')}><span className={cn('grid h-9 w-9 place-items-center rounded-lg', goal.completed ? 'bg-emerald-500 text-white' : 'bg-white text-slate-400')}>{goal.completed ? <Check size={17} /> : <Target size={17} />}</span><span className="flex-1"><strong className="block text-xs font-bold">{goal.title}</strong><span className="mt-1 block text-[11px] text-slate-400">{goal.current}/{goal.target} complete</span></span><span className="text-xs font-bold text-orange-500">+{goal.coins}</span></div>)}</div></Card><Card><SectionTitle title="Achievements" action={<Award size={17} className="text-orange-500" />} /><div className="grid gap-2 sm:grid-cols-2">{displayAchievements.map((achievement) => <div key={achievement.id} className={cn('rounded-xl border p-3', achievement.unlocked ? 'border-orange-100 bg-orange-50/60' : 'border-slate-100 bg-cloud opacity-60')}><div className="flex items-start justify-between"><span className={cn('grid h-8 w-8 place-items-center rounded-lg', achievement.unlocked ? 'bg-orange-400 text-white' : 'bg-slate-200 text-slate-400')}><Award size={15} /></span><span className="text-[10px] font-bold text-orange-500">+{achievement.coins}</span></div><p className="mt-3 text-xs font-bold">{achievement.title}</p><p className="mt-1 text-[11px] leading-4 text-slate-400">{achievement.description}</p></div>)}</div></Card></div><Card className="mt-5"><SectionTitle title="Recent activity" action={<button className="text-xs font-bold text-brand">See all</button>} />{transactions.length ? <div className="divide-y divide-slate-100">{transactions.slice(0, 5).map((transaction) => <div key={transaction._id || transaction.transaction_id} className="flex items-center gap-3 py-3"><span className="grid h-8 w-8 place-items-center rounded-lg bg-emerald-50 text-emerald-600"><Zap size={15} /></span><span className="flex-1 text-xs font-semibold">{transaction.description}</span><span className={cn('text-xs font-bold', transaction.transaction_type === 'spend' ? 'text-slate-500' : 'text-emerald-600')}>{transaction.transaction_type === 'spend' ? '-' : '+'}{transaction.amount}</span></div>)}</div> : <div className="flex items-center gap-3 py-4 text-sm text-slate-400"><Sparkles size={17} className="text-brand" /> Complete a check-in to see your first calm coin activity.</div>}</Card></>
}

function App() {
  return <Routes>
    <Route path="/" element={<Landing />} />
    <Route path="/login" element={<AuthPage />} />
    <Route path="/register" element={<AuthPage register />} />
    <Route element={<AppShell />}>
      <Route path="/dashboard" element={<Dashboard />} />
      <Route path="/chat" element={<Chat />} />
      <Route path="/journal" element={<Journal />} />
      <Route path="/books" element={<Books />} />
      <Route path="/music" element={<Music />} />
      <Route path="/therapists" element={<Therapists />} />
      <Route path="/coins" element={<CoinsPage />} />
    </Route>
    <Route path="*" element={<Navigate to="/" replace />} />
  </Routes>
}

export default App


